/*
 * Native replay of a Copilot C99 monitor generated by NASA Ogma from the
 * source-pinned FRET Lift+Cruise LPC_REARPROP historical-always requirement.
 * Each invocation is a new process to reset monitor state between traces.
 */
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include "monitor.h"

bool rearprop = false;
bool hover_control_mode = false;
static int violations = 0;

void handlerLPC_REARPROP(void) { violations++; }

int main(int argc, char **argv) {
  if (argc != 2) return 10;
  const int cases[3][3][2] = {
    {{1, 0}, {0, 1}, {1, 0}},
    {{1, 0}, {1, 1}, {0, 1}},
    {{1, 0}, {0, 0}, {0, 1}}
  };
  const int expected[3][3] = {
    {0, 0, 0},
    {0, 1, 2},
    {0, 1, 2}
  };
  char *end = NULL;
  const long which = strtol(argv[1], &end, 10);
  if (end == argv[1] || *end != '\0' || which < 0 || which > 2) return 11;
  for (int t = 0; t < 3; t++) {
    rearprop = cases[which][t][0] != 0;
    hover_control_mode = cases[which][t][1] != 0;
    step();
    printf("case=%ld step=%d rearprop=%d hover=%d violations=%d expected=%d\n",
           which, t, rearprop, hover_control_mode, violations, expected[which][t]);
    if (violations != expected[which][t]) return 20 + t;
  }
  puts("PASS: native Copilot prefix verdict preserves FRET historical-always source");
  return 0;
}
